def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid separator that divides the grid into equal-sized panels.
    sep = None
    for r in range(h):
        if h - r - 1 == r and len(set(grid[r])) == 1:
            sep = ("row", r)
            break
    if sep is None:
        for c in range(w):
            if w - c - 1 == c and all(row[c] == grid[0][c] for row in grid):
                sep = ("col", c)
                break

    if sep[0] == "row":
        k = sep[1]
        a, b = grid[:k], grid[k + 1:]
    else:
        k = sep[1]
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    equal_values = [a[r][c] for r in range(len(a)) for c in range(len(a[0]))
                    if a[r][c] == b[r][c]]
    base = max(set(equal_values), key=equal_values.count) if equal_values else 0

    return [[3 if a[r][c] == b[r][c] else base
             for c in range(len(a[0]))] for r in range(len(a))]
